@using sv_1364cca0ffa846768dee014bc84e5491.Services

<div class="channel-list">
    <div class="channel-list-header">
        <h5>Channels</h5>
    </div>
    <div class="channel-items">
        @foreach (var channel in Channels)
        {
            <button class="channel-item @(channel.Id == SelectedChannelId ? "active" : "")"
                    @onclick="() => OnChannelSelected.InvokeAsync(channel.Id)">
                <div class="channel-name">
                    <span class="hash">#</span> @channel.Name
                    @if (channel.UnreadCount > 0)
                    {
                        <span class="unread-badge">@channel.UnreadCount</span>
                    }
                </div>
                @if (!string.IsNullOrWhiteSpace(channel.Description))
                {
                    <div class="channel-desc">@Truncate(channel.Description, 40)</div>
                }
            </button>
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired] public List<Channel> Channels { get; set; } = [];
    [Parameter] public int? SelectedChannelId { get; set; }
    [Parameter] public EventCallback<int> OnChannelSelected { get; set; }

    private static string Truncate(string text, int maxLength) =>
        text.Length <= maxLength ? text : text[..maxLength] + "…";
}

.channel-list {
    display: flex;
    flex-direction: column;
    height: 100%;
    background: #2b2d31;
    color: #b5bac1;
}

.channel-list-header {
    padding: 1rem;
    border-bottom: 1px solid #1e1f22;
}

.channel-list-header h5 {
    margin: 0;
    color: #fff;
    font-size: 1rem;
    font-weight: 600;
}

.channel-items {
    flex: 1;
    overflow-y: auto;
    padding: 0.5rem;
}

.channel-item {
    display: block;
    width: 100%;
    text-align: left;
    background: none;
    border: none;
    border-radius: 6px;
    padding: 0.5rem 0.75rem;
    margin-bottom: 0.15rem;
    cursor: pointer;
    color: #b5bac1;
    transition: background 0.15s;
}

.channel-item:hover {
    background: #35373c;
    color: #dbdee1;
}

.channel-item.active {
    background: #404249;
    color: #fff;
}

.channel-name {
    display: flex;
    align-items: center;
    gap: 0.25rem;
    font-weight: 500;
    font-size: 0.9rem;
}

.hash {
    opacity: 0.6;
}

.unread-badge {
    margin-left: auto;
    background: #f23f43;
    color: #fff;
    font-size: 0.7rem;
    font-weight: 700;
    border-radius: 10px;
    padding: 0.1rem 0.4rem;
    min-width: 1.1rem;
    text-align: center;
}

.channel-desc {
    font-size: 0.75rem;
    opacity: 0.7;
    margin-top: 0.1rem;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

