@using sv_1364cca0ffa846768dee014bc84e5491.Services

<div class="message-area">
    @if (ChannelName is not null)
    {
        <div class="channel-header">
            <h4># @ChannelName</h4>
            @if (!string.IsNullOrWhiteSpace(ChannelDescription))
            {
                <span class="channel-description">@ChannelDescription</span>
            }
        </div>
    }

    <div class="message-list" @onscroll="HandleScroll" @ref="messageListRef">
        @if (IsLoadingMore)
        {
            <div class="loading-indicator">Loading older messages...</div>
        }
        @foreach (var message in Messages)
        {
            <MessageItem Message="message"
                         ThreadInfo="GetThreadInfo(message.Id)"
                         OnOpenThread="() => OnOpenThread.InvokeAsync(message.Id)"
                         OnReact="(emoji) => OnReact.InvokeAsync((message.Id, emoji))" />
        }
    </div>

    <MessageInput Placeholder="@($"Message #{ChannelName}")" ButtonLabel="Send"
                  OnSubmit="OnSendMessage" />
</div>

@code {
    [Parameter, EditorRequired] public List<Message> Messages { get; set; } = [];
    [Parameter] public string? ChannelName { get; set; }
    [Parameter] public string? ChannelDescription { get; set; }
    [Parameter] public List<ThreadSummary> ThreadSummaries { get; set; } = [];
    [Parameter] public bool IsLoadingMore { get; set; }
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }
    [Parameter] public EventCallback<string> OnSendMessage { get; set; }
    [Parameter] public EventCallback OnLoadMore { get; set; }

    private ElementReference messageListRef;

    private ThreadSummary? GetThreadInfo(int messageId) =>
        ThreadSummaries.FirstOrDefault(t => t.RootMessageId == messageId);

    private async Task HandleScroll()
    {
        // Scroll-to-top detection is handled via JS interop in the page
        // This is a placeholder for the event wiring
        await Task.CompletedTask;
    }
}

