        {
            module = await JS.InvokeAsync<IJSObjectReference>("import",
                "./_content/sv-1364cca0ffa846768dee014bc84e5491/Components/Chat/MessageArea.razor.js");
            dotNetRef = DotNetObjectReference.Create(this);
            await module.InvokeVoidAsync("registerScrollHandler", messageListRef, dotNetRef);
        }
    }

